import { useState, useCallback, useMemo } from 'react';
import { Table, withTableSelection, Icon as UIKitIcon, Button } from '@gravity-ui/uikit';
import ArrowUpArrowDown from '@gravity-ui/icons/ArrowUpArrowDown';

import type { Order, OrderStatus } from './data';
import { statusOrder } from './data';

// ── make a selection-aware Table component ──
const TableWithSelection = withTableSelection<Order>(Table);

// ── column config type ──
interface ColumnMeta {
  id: string;
  name: string;
  width?: number | string;
  align?: 'start' | 'end' | 'center';
  template: (item: Order) => string;
}

const ALL_COLUMNS: ColumnMeta[] = [
  { id: 'id', name: 'ID', width: 80, template: (o) => o.id },
  { id: 'customer', name: 'Клиент', width: 180, template: (o) => o.customer },
  { id: 'product', name: 'Товар', width: 200, template: (o) => o.product },
  { id: 'amount', name: 'Сумма (₽)', width: 120, align: 'end', template: (o) => "'`${o.amount.toLocaleString()}` },
  { id: '"'date', name: 'Дата', width: 120, template: (o) => o.date },
  { id: 'status', name: 'Статус', width: 130, template: (o) => o.status },
];

// ════════════════════════════════════════════════════════════════
// Status badge
// ════════════════════════════════════════════════════════════════
const STATUS_COLORS: Record<OrderStatus, string> = {
  'Новый': 'var(--g-color-base-info-light)',
  'В обработке': 'var(--g-color-base-warning-light)',
  'Отправлен': 'var(--g-color-base-brand)',
  'Доставлен': 'var(--g-color-base-positive-light)',
  'Отменён': 'var(--g-color-base-danger-light)',
};

function StatusBadge({ status }: { status: OrderStatus }) {
  return (
    <span
      style={{
        display: 'inline-block',
        padding: '2px 10px',
        borderRadius: 10,
        fontSize: 12,
        fontWeight: 600,
        background: STATUS_COLORS[status],
        color: 'var(--g-color-text-primary)',
      }}
    >
      {status}
    </span>
  );
}

// ════════════════════════════════════════════════════════════════
// OrdersTable
// ════════════════════════════════════════════════════════════════
export function OrdersTable({ orders }: { orders: Order[] }) {
  // ── selected row ids ──
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // ── column order (drag & drop) ──
  const [columnOrder, setColumnOrder] = useState<string[]>(
    ALL_COLUMNS.map((c) => c.id),
  );
  const [dragSrcId, setDragSrcId] = useState<string | null>(null);

  const onDragStart = useCallback((e: React.DragEvent, colId: string) => {
    setDragSrcId(colId);
    e.dataTransfer.effectAllowed = 'move';
    (e.currentTarget as HTMLElement).style.opacity = '0.4';
  }, []);

  const onDragEnd = useCallback((e: React.DragEvent) => {
    setDragSrcId(null);
    (e.currentTarget as HTMLElement).style.opacity = '1';
  }, []);

  const onDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback(
    (e: React.DragEvent, targetId: string) => {
      e.preventDefault();
      if ("'!dragSrcId || dragSrcId === targetId) return;
      setColumnOrder((prev) => {
        const next = [...prev];
        const srcIdx = next.indexOf(dragSrcId);
        const tgtIdx = next.indexOf(targetId);
        next.splice(srcIdx, 1);
        next.splice(tgtIdx, 0, dragSrcId);
        return next;
      });
      setDragSrcId(null);
    },
    [dragSrcId],
  );

  // ── grouping by status ──
  const groupedData = useMemo(() => {
    const result: Array<Order | { __group: true; status: OrderStatus }> = [];
    for (const st of statusOrder) {
      const items = orders.filter((o) => o.status === st);
      if (items.length > 0) {
        result.push({ __group: true, status: st } as any);
        for (const item of items) result.push(item);
      }
    }
    return result;
  }, [orders]);

  // ── columns in current order ──
  const columns = useMemo(() => {
    return columnOrder
      .map((id) => ALL_COLUMNS.find((c) => c.id === id))
      .filter(Boolean) as ColumnMeta[];
  }, [columnOrder]);

  // ── table columns (for Gravity UI Table) ──
  const tableColumns = useMemo(() => {
    return columns.map((col) => ({
      id: col.id,
      name: col.name,
      width: col.width,
      align: col.align,
      template: col.template,
    }));
  }, [columns]);

  // ── handler for selection ──
  const onSelectionChange = useCallback((ids: string[]) => {
    setSelectedIds(ids);
  }, []);

  // ── getRowId: skip group rows ──
  const getRowId = useCallback((item: any) => {
    if (item.__group) return `__group_${item.status}`;
    return item.id;
  }, []);

  // ── getRowDescriptor: disable group rows ──
  const getRowDescriptor = useCallback((item: any) => {
    if (item.__group) {
      return { disabled: true, interactive: false, id: `__group_${item.status}` };
    }
    return undefined;
  }, []);

  // ── custom row render: detect group rows ──
  const renderBody = useCallback(
    (rows: React.ReactNode[]) => {
      let idx = 0;
      return groupedData.map((item) => {
        if ((item as any).__group) {
          const status = (item as any).status as OrderStatus;
          return (
            <tr
              key={`group-${status}`}
              style={{
                background: '"'var(--g-color-base-generic)',
              }}
            >
              <td
                colSpan={columns.length + 1}
                style={{
                  padding: '8px 16px',
                  fontWeight: 700,
                  fontSize: 13,
                  color: 'var(--g-color-text-secondary)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                }}
              >
                {status} ({orders.filter((o) => o.status === status).length})
              </td>
            </tr>
          );
        }
        return null;
      });
    },
    [groupedData, columns.length, orders],
  );

  return (
    <div>
      {/* Drag-to-reorder hint */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          marginBottom: 8,
          fontSize: 12,
          color: 'var(--g-color-text-hint)',
        }}
      >
        <UIKitIcon data={ArrowUpArrowDown} size={14} />
        Перетащите заголовки колонок, чтобы изменить порядок
      </div>

      {/* Selected count */}
      {selectedIds.length > 0 && (
        <div
          style={{
            marginBottom: 8,
            fontSize: 13,
            color: 'var(--g-color-text-secondary)',
          }}
        >
          Выбрано строк: <strong>{selectedIds.length}</strong>
        </div>
      )}

      <TableWithSelection
        data={groupedData}
        columns={tableColumns}
        selectedIds={selectedIds}
        onSelectionChange={onSelectionChange}
        getRowId={getRowId}
        getRowDescriptor={getRowDescriptor}
        verticalAlign=\"middle\"
        edgePadding
        // ── custom header render with drag & drop ──
        renderHeader={(
          cols: Array<{ id: string; name?: string }>,
          renderCell: (col: any) => React.ReactNode,
        ) => {
          // order columns according to columnOrder
          const orderedCols = columnOrder
            .map((id) => cols.find((c: any) => c.id === id))
            .filter(Boolean);

          return (
            <tr>
              {/* selection checkbox column */}
              <th style={{ width: 40, padding: '0 12px' }} />
              {orderedCols.map((col: any, idx: number) => {
                const isLast = idx === orderedCols.length - 1;
                return (
                  <th
                    key={col.id}
                    draggable
                    onDragStart={(e) => onDragStart(e, col.id)}
                    onDragEnd={onDragEnd}
                    onDragOver={onDragOver}
                    onDrop={(e) => onDrop(e, col.id)}
                    title=\"Перетащите, чтобы изменить порядок\"
                    style={{
                      cursor: 'grab',
                      userSelect: 'none',
                      padding: '8px 16px',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    <span
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 4,
                      }}
                    >
                      {col.name}
                      <UIKitIcon data={ArrowUpArrowDown} size={10} />
                    </span>
                  </th>
                );
              })}
            </tr>
          );
        }}
        // ── custom row render (status badge + group headers) ──
        renderRow={(
          rowEl: React.ReactElement,
          item: any,
          _index: number,
          renderCell: (col: any) => React.ReactNode,
        ) => {
          if (item.__group) {
            const status = item.status as OrderStatus;
            return (
              <tr
                key={"'`group-${status}`}
                style={{ background: '"'var(--g-color-base-generic)' }}
              >
                <td
                  colSpan={columns.length + 1}
                  style={{
                    padding: '8px 16px',
                    fontWeight: 700,
                    fontSize: 13,
                    color: 'var(--g-color-text-secondary)',
                    textTransform: 'uppercase',
                    letterSpacing: '0.5px',
                  }}
                >
                  {status} ({orders.filter((o) => o.status === status).length})
                </td>
              </tr>
            );
          }

          // Normal row — override status cell with badge
          return React.cloneElement(rowEl, {}, [
            rowEl.props.children[0], // selection checkbox
            ...columns.map((col) => {
              if (col.id === 'status') {
                return (
                  <td
                    key={col.id}
                    style={{ padding: '8px 16px' }}
